// Order-24 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same transfer function.
module iir24_v2 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] r9;
  reg [15:0] r10;
  reg [15:0] r11;
  reg [15:0] r12;
  reg [15:0] r13;
  reg [15:0] r14;
  reg [15:0] r15;
  reg [15:0] r16;
  reg [15:0] r17;
  reg [15:0] r18;
  reg [15:0] r19;
  reg [15:0] r20;
  reg [15:0] r21;
  reg [15:0] r22;
  reg [15:0] r23;
  reg [15:0] r24;
  reg [15:0] y2;
  reg [15:0] y3;
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; y3<=0; r1<=0; r2<=0; r3<=0; r4<=0; r5<=0; r6<=0; r7<=0; r8<=0; r9<=0; r10<=0; r11<=0; r12<=0; r13<=0; r14<=0; r15<=0; r16<=0; r17<=0; r18<=0; r19<=0; r20<=0; r21<=0; r22<=0; r23<=0; r24<=0; end
    else begin
      y <= ((63*x + r1 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF);
      r2 <= (15*x + r1) & 16'hFFFF; r3 <= (4*x + r1) & 16'hFFFF; r4 <= (35*x + r1) & 16'hFFFF; r5 <= (41*x + r1) & 16'hFFFF; r6 <= (47*x + r1) & 16'hFFFF; r7 <= (40*x + r1) & 16'hFFFF; r8 <= (2*x + r1) & 16'hFFFF; r9 <= (60*x + r1) & 16'hFFFF; r10 <= (19*x + r1) & 16'hFFFF; r11 <= (5*x + r1) & 16'hFFFF; r12 <= (12*x + r1) & 16'hFFFF; r13 <= (50*x + r1) & 16'hFFFF; r14 <= (28*x + r1) & 16'hFFFF; r15 <= (46*x + r1) & 16'hFFFF; r16 <= (49*x + r1) & 16'hFFFF; r17 <= (15*x + r1) & 16'hFFFF; r18 <= (22*x + r1) & 16'hFFFF; r19 <= (36*x + r1) & 16'hFFFF; r20 <= (52*x + r1) & 16'hFFFF; r21 <= (8*x + r1) & 16'hFFFF; r22 <= (31*x + r1) & 16'hFFFF; r23 <= (50*x + r1) & 16'hFFFF; r24 <= (57*x + r1) & 16'hFFFF;
      y2 <= ((9*y)>>4) & 16'hFFFF;
      y3 <= ((5*y2)>>4) & 16'hFFFF;
    end
  end
endmodule
